export function projectIndia(lat: number, lng: number) {
  return {
    x: ((lng - INDIA_VIEW.west) / (INDIA_VIEW.east - INDIA_VIEW.west)) * INDIA_VIEW.w,
    y: ((INDIA_VIEW.north - lat) / (INDIA_VIEW.north - INDIA_VIEW.south)) * INDIA_VIEW.h,
  };
}

export function projectWorld(lat: number, lng: number) {
  return {
    x: ((lng + 180) / 360) * WORLD_VIEW.w,
    y: ((90 - lat) / 180) * WORLD_VIEW.h,
  };
}
